const item = $input.first().json;
const base = $env.KANALLAR_BASE_URL || '';
const topic = $('When called by another workflow').first().json;
const msg = [
  `Kanal: ${topic.channel_id || ''}`,
  `Konu: ${topic.topic || ''}`,
  `Açı: ${topic.angle || ''}`,
  `Hook: ${topic.hook_candidate || ''}`,
  `Neden: ${topic.why || ''}`,
  '',
  `Token: ${item.token}`,
  `Decide: POST ${base}/api/approvals/topic/decide?token=...&decision=APPROVE|REJECT|NEW_IDEAS`
].join('\n');
return [{ json: { ...item, ...topic, telegram_text: msg, resume_hint: 'Wire Telegram + Wait webhook in n8n UI with bot credential' } }];
